  'Studio D': 'c_18801gc6ck77gho7jl0e1fug94u92@resource.calendar.google.com',
  'Studio E': 'c_18807te03d2sqh0lmtal9sbb04gao@resource.calendar.google.com',
  'Studio F': 'c_188em7d58podeju3i8q6juqlufkls@resource.calendar.google.com',
  'Studio M': 'c_1885k4adm87fqjd2j3j2usqftph5c@resource.calendar.google.com',
  'M1': 'c_1889v46vd62fkjk3i7r1hsfem7tcm@resource.calendar.google.com',
  'M2': 'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com',
  'M3': 'c_188d7dkqgnfs6hu4iunlu5ogftct0@resource.calendar.google.com',
  'M4': 'c_18869nhmsj2uki8mljoi48v1cj7l4@resource.calendar.google.com',
  'M5': 'c_1889h30ci9noqjcbnoogad9qk75vq@resource.calendar.google.com',
  'M6': 'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com',
  'M7': 'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com',
  'M8': 'c_1884cu2cc84iujsjnu03s21f0ct9q@resource.calendar.google.com',
  'Salin': 'c_1887hh5rsv6q4gt8hnu6ered170lg@resource.calendar.google.com',
  'Katha': 'c_1881169pcpn12gsnm6i7sc0gjk7gk@resource.calendar.google.com',
  'Likha': 'c_1886t6cjgrq0ihgpime01uibcqsg6@resource.calendar.google.com',
  'Lobby': 'c_188227mpeagjuhi7gqlgns1di14be@resource.calendar.google.com'
};

// --- required fields ----------------------------------------------------
// $fromAI inputs carry defaults so a partial tool call reaches this node instead
// of failing n8n's schema validation, which killed the whole turn and dropped the
// conversation into the error branch. Missing pieces are answered, not crashed.
const missing = [];
if (!String(REQ.summary || '').trim())   missing.push('a title');
if (!String(REQ.start_iso || '').trim()) missing.push('a start time');
if (!String(REQ.end_iso || '').trim())   missing.push('an end time');
if (!String(REQ.rooms || '').trim())     missing.push('a room');
if (missing.length) {
  return [{ json: { verdict:'REJECTED', reason:'MISSING_DETAILS', missing,
    human:'Nothing was booked - the booking is still missing ' + missing.join(', ')
        + '. Ask the requester for what is missing, then present the summary again.' } }];
}

// --- on-behalf bookings still need a real, distinct client ----------------
// The person a session is booked FOR (Booked by: X (for Y)) is a colleague, never the
// client, and must not land in the title Client segment. Prompt-only rules did not hold:
// the model laundered the booked-for name into the client/title when no client was given
// (Howard, 2026-09-23). Enforced here, only for External studio bookings that name a for-person.
const bookedFor = ((String(REQ.description || '').match(/\(for\s+([^)]+)\)/i) || [])[1] || '').trim();
if (bookedFor && String(REQ.bookingType || '').trim().toLowerCase() === 'external') {
  const clientNow = String(REQ.client || '').trim();
  const titleClient = (String(REQ.summary || '').split(' / ')[1] || '').trim();
  const isFor = (s) => !!s && s.toLowerCase() === bookedFor.toLowerCase();
  if (!clientNow || isFor(clientNow) || isFor(titleClient)) {
    return [{ json: { verdict:'REJECTED', reason:'MISSING_CLIENT',
      human:'Nothing was booked. ' + bookedFor + ' is who this session is booked FOR, not the client - so ' + bookedFor + ' must not be the client and must not appear in the calendar title. A studio booking still needs its own client. Ask the requester who the client is, rebuild the title as PROJECT / Client / initials, and present the summary again.' } }];
  }
}

// Rooms and session types are passed in by Room Table, which already read them
// this turn. Re-reading Airtable here fetched the same two tables a second time
// and cost about 2.2 seconds a booking.
//
// If a session type was supplied and the data did not arrive, refuse. The
// duration and ranking guards are written to stay silent when they cannot find
// a session type, so proceeding would quietly book with two guards disabled.
const REF = (function(){
  try { return JSON.parse(String(REQ.reference_data || '') || '{}'); } catch (e) { return {}; }
})();
const refRooms = REF.rooms || [];
const refTypes = REF.types || [];
if (String(REQ.session_type || '').trim() && !(refRooms.length && refTypes.length)) {
  return [{ json: { verdict:'REJECTED', reason:'NO_REFERENCE_DATA',
    human:'Nothing was booked - the room and session-type data did not reach the booking step, so the '
        + 'duration and room checks could not run. Tell the requester it failed and to try again.' } }];
}
const nameById = {};
// Vocal booths are carried on reference data by Room Table, read from the
// Airtable checkbox. Used by the ranking check below: a booth is a second room
// on the same event, not the room the session runs in.
const isVocalBooth = {};
// `booth` covers any room typed Recording Booth, vocal or not. The ranking check
// exempts a booth being paired with a ranked room; Studio E is a booth but not a
// vocal booth, so it is bookable when asked for by name and never offered first.
const isBooth = {};
for (const r of refRooms) {
  nameById[r.id] = r.name;
  const key = String(r.name || '').trim().toLowerCase();
  if (r.vocalBooth === true) isVocalBooth[key] = true;
  if (r.booth === true || r.vocalBooth === true) isBooth[key] = true;
}
const stRec = refTypes.filter(function(t){
  return String(t.type || '').trim().toLowerCase() === String(REQ.session_type || '').trim().toLowerCase();
})[0] || null;

// --- the date has passed ------------------------------------------------
// v39's Create Event threw on this and the guard did not survive the move into
// this sub-workflow, so nothing has stopped a booking in the past since v37.
// Same rule as v39: anything before midnight today in Manila is refused, so a
// session earlier today is still bookable.
(function(){
  const raw = String(REQ.start_iso || '').trim();
  if (!raw) return;                                   // MISSING_DETAILS covers this
  const t = new Date(raw).getTime();
  if (!t) return;                                     // unparseable - let the calendar reject it
  const nowShifted = new Date(Date.now() + 8 * 3600 * 1000);
  const manilaMidnight = Date.UTC(nowShifted.getUTCFullYear(), nowShifted.getUTCMonth(),
                                  nowShifted.getUTCDate()) - 8 * 3600 * 1000;
  if (t < manilaMidnight) { REQ.__past = true; }
})();
if (REQ.__past) {
  return [{ json: { verdict:'REJECTED', reason:'PAST_DATE', requested: REQ.start_iso,
    human:'Nothing was booked - ' + String(REQ.start_iso).slice(0, 10) + ' has already passed. '
        + 'Tell the requester the date is in the past and ask for the correct one. Do not book '
        + 'anything until they give you a new date.' } }];
}

// --- confirmation gate -------------------------------------------------
// `confirmed` is computed by Gate Context in the calling workflow from real
// Slack history: the last thing Jessie said must be a summary ending in the
// marker line, and the requester must have replied after it. Send Reply runs
// after the agent, so a summary written in THIS turn is not in Slack yet and
// cannot satisfy this. The model never supplies this value.
const confirmed = REQ.confirmed === true || String(REQ.confirmed).toLowerCase() === 'true';
const roomList = String(REQ.rooms || '').split(',').map(r => r.trim()).filter(r => r.length);
const mBoothOnly = roomList.length > 0 && roomList.every(r => /^M[1-8]$/i.test(r));
// A recurring series always needs confirmation, even for M Booths: the immediate-book
// exception is for a single quick hold, not for creating many events at once.
const series = REQ.series === true || String(REQ.series).toLowerCase() === 'true';
if (!confirmed && !(mBoothOnly && !series)) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_CONFIRMED',
    human:'Nothing was booked, because the requester has not approved this booking yet. '
        + 'Present the complete booking summary now, end it with the line "Confirm to book.", '
        + 'and stop. Book it only after they reply approving it. Do not call this tool again '
        + 'in this response.' } }];
}

// --- duration limits ---------------------------------------------------
// Session Types holds Min/Max Duration (mins). Enforced here because this is
// the only path that creates a booking. Silent when the session type was not
// supplied or not found - an internal room has no session type, and a lookup
// failure must not block a booking that is otherwise fine.
const ST = stRec ? { 'Type': stRec.type, 'Min Duration (mins)': stRec.min,
                     'Max Duration (mins)': stRec.max } : {};
const minD = Number(ST['Min Duration (mins)']);
const maxD = Number(ST['Max Duration (mins)']);
const allDay = REQ.all_day === true || String(REQ.all_day).toLowerCase() === 'true';

// Min/Max Duration is what a session of that kind usually runs. It is not a
// limit - Tara, 2026-08-30: "duration is just suggestion, or average. its not
// MAXIMUM ALLOWED. it could go on for 8 hours." This used to refuse the booking
// and demand an override, and the model repeated the refusal back as "the
// maximum allowed duration", which is not true of any session here.
//
// So it is only ever an observation now, attached to a booking that goes ahead.
// It holds ONLY the sentence the requester should see. It used to carry the
// model's instructions too - "mention it once in passing, do not call it a
// limit" - and because `human` is relayed close to verbatim, that reached the
// requester word for word on 2026-08-30. How to phrase it belongs in the
// prompt, which already says it; this field is the fact, nothing else.
// A length exactly on the boundary is normal, not a deviation: 180 minutes of
// Post Mixing against a 60-180 range was being flagged as though it were over.
let durationNote = '';
const mins = Math.round((new Date(REQ.end_iso).getTime() - new Date(REQ.start_iso).getTime()) / 60000);
if (!allDay && mins <= 0) {
  return [{ json: { verdict:'REJECTED', reason:'DURATION_INVALID', requested_mins: mins,
    human: 'Nothing was booked - the end time is not after the start time. Check the times with the '
         + 'requester and try again.' } }];
}
// A blank Min or Max in Airtable arrives as 0, and 0 is finite - so a session
// type with no Max was treated as having a maximum of zero. Localization
// Editing on 2026-09-01: a 120-minute booking came back "That is a bit longer
// than Localization Editing sessions usually run (240-0 minutes is typical)",
// which is both wrong and incoherent, and it would have fired on every booking
// of that type. A bound only counts when it is a positive number.
const hasMin = Number.isFinite(minD) && minD > 0;
const hasMax = Number.isFinite(maxD) && maxD > 0;
if (!allDay && mins > 0 && (hasMin || hasMax)) {
  const typical = hasMin && hasMax ? (minD + '-' + maxD + ' minutes')
                : hasMax ? ('up to ' + maxD + ' minutes')
                : ('at least ' + minD + ' minutes');
  const kind = ST['Type'] || 'session';
  if (hasMax && mins > maxD)
    durationNote = 'That is a bit longer than ' + kind + ' sessions usually run ('
                 + typical + ' is typical).';
  else if (hasMin && mins < minD)
    durationNote = 'That is a bit shorter than ' + kind + ' sessions usually run ('
                 + typical + ' is typical).';
}

// --- what actually goes on the calendar entry ----------------------------
// The engineer used to ride inside a free-text description the model composed,
// and on 2026-08-30 it arrived empty: the event read "| Booked by: Tara Lim |
// ref: ..." with no engineer at all, and a leading pipe. Older bookings have
// "Engineer: Tara Lim (Post Engineer) | Booked by: ...", so this was a
// regression, not a gap. A named input gets filled where a paragraph does not,
// and the line is assembled here rather than by the model.
const segs = String(REQ.description || '').split('|').map(s => s.trim()).filter(Boolean);
const eng = String(REQ.engineer || '').trim();
if (eng && !segs.some(s => /^engineer\s*:/i.test(s))) segs.unshift('Engineer: ' + eng);
// Only read the client record when a client was actually given. An empty client
// used to make the Airtable formula SEARCH('') - which matches every row - so
// Get Client returned all 105 clients and .first() was whoever came back first.
// A booking for one client was assembled from another client's record.
// Same fallback the Get Client formula uses, so the two cannot disagree about
// whether a client was identified.
let clientGiven = String(REQ.client || '').trim();
if (!clientGiven) {
  const tparts = String(REQ.summary || '').split('/');
  if (tparts.length >= 3) { clientGiven = tparts[1].trim(); }
}
let techReq = '';
if (clientGiven) {
  try { techReq = String(((($('Get Client').first().json || {}).fields) || {})['Technical Requirements'] || '').trim(); }
  catch (e) { techReq = ''; }
}
// External / Personal rides on the event as a description segment (the calendar
// node has no extendedProperties field). Structured input, not model-composed.
const bookingType = String(REQ.bookingType || '').trim();
if (bookingType) segs.push('Type: ' + bookingType);
const dept = String(REQ.department || '').trim();
if (dept) segs.push('Dept: ' + dept);
segs.push('Tech requirements: ' + (techReq || 'None'));
const finalDescription = segs.join(' | ');

// The client's name in the title comes from what the requester typed, so
// "EDGE / jem lim / TL" happened. Only the spelling is corrected, and only when
// it is the same name - a different name is left alone rather than overwritten.
let finalSummary = String(REQ.summary || '');
try {
  const canon = clientGiven
    ? String(((($('Get Client').first().json || {}).fields) || {})['Name'] || '').trim() : '';
  const parts = finalSummary.split('/').map(s => s.trim());
  if (canon && parts.length >= 3 && parts[1].toLowerCase() === canon.toLowerCase() && parts[1] !== canon) {
    parts[1] = canon;
    finalSummary = parts.join(' / ');
  }
} catch (e) {}

// --- room ranking ------------------------------------------------------
// Session Types ranks rooms per type: Priority first, Last Resort only when
// every Priority room is taken. Both lists are record ids, so Get Rooms
// returns every bookable room and the ids are resolved here. The model is not
// consulted and cannot skip this.
const priorityIds = stRec ? [].concat(stRec.priority || []) : [];
const lastIds     = stRec ? [].concat(stRec.last || [])     : [];

const roomOverride = REQ.room_override === true || String(REQ.room_override).toLowerCase() === 'true';
// The ranking is a recommendation, not a rule: the studio does run sessions in
// non-standard rooms when it has to. Refuse once so the requester is told, then
// book it if they say to go ahead - the same shape as the duration limits.
if ((priorityIds.length || lastIds.length) && !allDay && !roomOverride) {
  const nameOf = nameById;
  const priorityNames = priorityIds.map(id => nameOf[id]).filter(Boolean);
  const lastNames     = lastIds.map(id => nameOf[id]).filter(Boolean);
  const asked = String(REQ.rooms || '').split(',').map(r => r.trim()).filter(r => r.length);
  const lower = a => a.map(x => x.toLowerCase());

  // a room in neither list is not run for this session type at all
  if (priorityNames.length || lastNames.length) {
    const known = lower(priorityNames.concat(lastNames));
    // The ranking answers which STUDIO runs a session type; it never lists booths.
    // Before this, pairing any booth with a VO Recording or Music Vocal Recording
    // was refused as ROOM_UNSUITABLE - "VO Recording is not run in Studio A" -
    // because no booth appears in those types' Priority or Last Resort lists,
    // while the prompt invited the pairing. Found 2026-09-03.
    // A booth is only exempt when a ranked room is also being booked: that is what
    // makes it a pairing rather than someone booking a booth on its own, which is
    // still refused.
    const hasSessionRoom = lower(asked).some(function(r){ return known.indexOf(r) !== -1; });
    const notRun = asked.filter(function(r){
      const lr = r.toLowerCase();
      if (known.indexOf(lr) !== -1) return false;
      if (hasSessionRoom && isBooth[lr]) return false;
      return true;
    });
    if (notRun.length) {
      return [{ json: { verdict:'REJECTED', reason:'ROOM_UNSUITABLE', unsuitable: notRun,
        priority: priorityNames, last_resort: lastNames,
        // ROOM_NOT_PRIORITY tells the model it may book the room anyway if the
        // requester insists; this refusal did not, so a room in neither list read
        // as a hard no. The studio does run VO Recording in Studios 3-6 when it
        // has to, with vocals recorded in-room - Howard, 2026-09-03. Both
        // refusals now offer the same way out, which is what room_override is for.
        human: ((stRec ? stRec.type : '') || 'That session type') + ' is not normally run in '
             + notRun.join(', ') + '. Nothing was booked. Suggest these instead: '
             + priorityNames.join(', ')
             + '. If they say to go ahead with what they asked for, book it.' } }];
    }
  }

  // a Last Resort room is only allowed when every Priority room is busy
  const askedLastResort = asked.filter(r => lower(lastNames).indexOf(r.toLowerCase()) !== -1
                                         && lower(priorityNames).indexOf(r.toLowerCase()) === -1);
  if (askedLastResort.length && priorityNames.length) {
    // occupancy computed inline: roomsOf() is declared below and closes over
    // `keys`, which is not initialised yet at this point in the script.
    const roomKeys = Object.keys(ROOMS);
    const exclude = String(REQ.exclude_event_id || '').trim();
    const busy = {};
    for (const ev of EVENTS) {
      if (!ev || !ev.id) continue;
      if (exclude && ev.id === exclude) continue;
      const s0 = new Date(ev.start && (ev.start.dateTime || ev.start.date)).getTime();
      const e0 = new Date(ev.end   && (ev.end.dateTime   || ev.end.date)).getTime();
      if (!(s0 < new Date(REQ.end_iso).getTime() && e0 > new Date(REQ.start_iso).getTime())) continue;
      const emails = (ev.attendees || []).map(a => String(a.email || '').toLowerCase());
      const loc = String(ev.location || '').toLowerCase();
      const firstSeg = String(ev.summary || '').split(' - ')[0].trim().toLowerCase();
      for (const k of roomKeys) {
        const lk = k.toLowerCase();
        if (emails.indexOf(ROOMS[k].toLowerCase()) !== -1 || (loc && loc.indexOf(lk) !== -1) || firstSeg === lk) {
          busy[lk] = true;
        }
      }
    }
    const freePriority = priorityNames.filter(r => !busy[r.toLowerCase()]);
    if (freePriority.length) {
      return [{ json: { verdict:'REJECTED', reason:'ROOM_NOT_PRIORITY',
        requested: askedLastResort, free_priority: freePriority, last_resort: lastNames,
        // Tara, 2026-08-30: never say "priority" or "last resort" to a requester -
        // it is internal vocabulary and it reads as a rule when it is a preference.
        human: 'Nothing was booked. ' + freePriority.join(', ') + ' would normally be used for '
             + ((stRec ? stRec.type : '') || 'this session type') + ' and ' + (freePriority.length > 1 ? 'are' : 'is')
             + ' free at that time. Suggest one of those instead of ' + askedLastResort.join(', ')
             + '. If they say to go ahead with what they asked for, book it.' } }];
    }
  }
}

const wantedNames = String(REQ.rooms || '').split(',').map(r => r.trim()).filter(r => r.length);
if (!wantedNames.length) {
  return [{ json: { verdict:'REJECTED', reason:'NO_ROOM', human:'No room was given, so nothing was booked.' } }];
}
const keys = Object.keys(ROOMS);
const wanted = [];
for (const name of wantedNames) {
  const hit = keys.find(k => k.toLowerCase() === name.toLowerCase());
  if (!hit) {
    return [{ json: { verdict:'REJECTED', reason:'UNKNOWN_ROOM',
      human:'I do not recognise the room "' + name + '", so nothing was booked.' } }];
  }
  wanted.push({ name: hit, id: ROOMS[hit].toLowerCase() });
}

// Work out which room an event occupies, from strongest signal to weakest.
// 1. resource attendee  2. location string  3. title's first segment, because
// internal-room bookings are titled "M2 - Peemo", "Lobby - Party", "KATHA - ...".
function roomsOf(ev) {
  const found = [];
  const emails = (ev.attendees || []).map(a => String(a.email || '').toLowerCase());
  const loc = String(ev.location || '').toLowerCase();
  const firstSeg = String(ev.summary || '').split(' - ')[0].trim().toLowerCase();
  for (const k of keys) {
    const lk = k.toLowerCase();
    if (emails.indexOf(ROOMS[k].toLowerCase()) !== -1) { found.push(k); continue; }
    if (loc && loc.indexOf(lk) !== -1) { found.push(k); continue; }
    if (firstSeg && firstSeg === lk) { found.push(k); }
  }
  return found;
}

const ms = v => new Date(v).getTime();
const reqStart = ms(REQ.start_iso), reqEnd = ms(REQ.end_iso);
const exclude = String(REQ.exclude_event_id || '').trim();
const conflicts = [], unverifiable = [];

for (const ev of EVENTS) {
  if (!ev || !ev.id) continue;
  if (exclude && ev.id === exclude) continue;

  const evStart = ms(ev.start && (ev.start.dateTime || ev.start.date));
  const evEnd   = ms(ev.end   && (ev.end.dateTime   || ev.end.date));
  if (!(evStart < reqEnd && evEnd > reqStart)) continue;
  // A consented placement (room_override) may use a booth despite its standing hold; the hold is
  // transparent+recurring. Skip it here so the sanctioned booking is not blocked by the very hold the
  // holder just approved. A normal booking (no override) still sees the hold and triggers M-Booth consent.
  if (REQ.room_override && ev.recurringEventId) continue;

  const evRooms = roomsOf(ev);
  if (!evRooms.length) {
    unverifiable.push({ summary: ev.summary || '(no title)',
      start: ev.start && (ev.start.dateTime || ev.start.date) });
    continue;
  }
  for (const w of wanted) {
    if (evRooms.indexOf(w.name) !== -1) {
      conflicts.push({ room: w.name, summary: ev.summary || '(no title)', start: ev.start && (ev.start.dateTime || ev.start.date), end: ev.end && (ev.end.dateTime || ev.end.date), id: ev.id || '', description: ev.description || '', transparent: (ev.transparency === 'transparent'), recurring: !!ev.recurringEventId });
      break;
    }
  }
}

if (conflicts.length) {
  const lines = conflicts.map(c => c.room + ' is taken by "' + c.summary + '"').join('; ');
  return [{ json: { verdict:'REJECTED', reason:'ROOM_OCCUPIED', conflicts,
    human: lines + '. Nothing was booked - tell the requester and offer 2-3 alternative slots.' } }];
}
if (unverifiable.length) {
  const names = unverifiable.map(u => '"' + u.summary + '"').join(', ');
  return [{ json: { verdict:'REJECTED', reason:'UNVERIFIABLE', unverifiable,
    human:'There is an event in that window I cannot identify a room for (' + names + '), so I could not '
        + 'confirm the room is free. Nothing was booked - ask the requester to check Google Calendar.' } }];
}
return [{ json: { verdict:'CLEAR', duration_note: durationNote,
  final_description: finalDescription, final_summary: finalSummary } }];

const ev = $input.first().json || {};
const REQ = $('When Executed by Another Workflow').first().json;
if (!ev.id) {
  return [{ json: { status:'FAILED',
    human:'The booking was not created - the calendar returned no event. Tell the requester it failed and ask how they want to proceed. Do not say it is booked.' } }];
}
const got = {
  start: (ev.start && (ev.start.dateTime || ev.start.date)) || '',
  end:   (ev.end   && (ev.end.dateTime   || ev.end.date))   || ''
};
const same = t => new Date(got[t]).getTime() === new Date(REQ[t + '_iso']).getTime();
if (!REQ.all_day && (!same('start') || !same('end'))) {
  return [{ json: { status:'MISMATCH', event_id: ev.id, created: got,
    human:'The event was created but the times do not match what was agreed. It is now ' + got.start + ' to ' + got.end + '. Tell the requester exactly that - do not confirm it as correct.' } }];
}
const declined = (ev.attendees || []).filter(a => a.responseStatus === 'declined').map(a => a.displayName || a.email);
if (declined.length) {
  return [{ json: { status:'ROOM_DECLINED', event_id: ev.id, declined,
    human:'The room declined the booking because it is already taken, so this booking is NOT valid. Tell the requester and offer 2-3 alternatives. Do not delete whatever holds the room.' } }];
}
// Room resources answer the invitation a few seconds after the event is created,
// so responseStatus is always 'needsAction' in this response. Reporting it as pending
// is noise on every booking. A genuine refusal shows up as 'declined', handled above.
// A duration outside the typical range rides along with the confirmation
// rather than blocking it - it is an observation, not a rule.
const note = (function(){ try { return String($('Check Conflicts').first().json.duration_note || ''); }
                          catch (e) { return ''; } })();
return [{ json: { status:'CREATED', event_id: ev.id, title: ev.summary,
  duration_note: note, human: note ? 'Booked. ' + note : 'Booked.' } }];

const v = $input.first().json || {};
return [{ json: {
  status: v.verdict || 'FAILED',
  reason: v.reason || 'CREATE_FAILED',
  conflicts: Array.isArray(v.conflicts) ? v.conflicts.map(c => ({ room: c.room, summary: c.summary, start: c.start, end: c.end })) : (v.conflicts || null),
  unverifiable: v.unverifiable || null,
  human: v.human || 'The booking failed and nothing was created. Tell the requester it did not go through.'
} }];

