={{ (function(){
  // The calendar query runs BEFORE Check Conflicts, so a malformed window fails
  // here as an HTTP 400 and the guards never run - the requester gets "tiny
  // hiccup" instead of MISSING_DETAILS. Seen 2026-09-03 on "book m4 for howard
  // tomorrow": start_iso "2027-09-04", end_iso "". M Booths are the exposed path
  // because they skip the confirmation gate and go straight to booking.
  // Only the QUERY is normalised. Check Conflicts still reads the raw values, so
  // MISSING_DETAILS and PAST_DATE keep firing on exactly what the model sent.
  var j = $('When Executed by Another Workflow').first().json;
  var norm = function(v){
    var s = String(v == null ? '' : v).trim();
    if (!s) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s + 'T00:00:00+08:00';
    return s;
  };
  var start = norm(j.start_iso);
  if (!start || isNaN(new Date(start).getTime())) start = new Date().toISOString();
  var end = norm(j.end_iso);
  if (!end || isNaN(new Date(end).getTime())
      || new Date(end).getTime() <= new Date(start).getTime()) {
    end = new Date(new Date(start).getTime() + 24 * 3600 * 1000).toISOString();
  }
  return { start: start, end: end };
})().start }}

