parameters.filterByFormula:
={{ (function(){
  var REQ = $('When Executed by Another Workflow').first().json;
  // The client is in the title whether or not the model remembered to pass it:
  // titles are PROJECT / Client / INITIALS. On 2026-08-30 a booking that named
  // the client in the message still arrived with client='' because the summary
  // happened to omit its Client line, and the session lost the client's
  // technical requirements - which is what the room gets set up from.
  var v = String(REQ.client || '').trim();
  if (!v) {
    var parts = String(REQ.summary || '').split('/');
    if (parts.length >= 3) { v = parts[1].trim(); }
  }
  if (!v) { return 'FALSE()'; }
  return "SEARCH(LOWER('" + v.replace(/'/g, "\\'").toLowerCase() + "'), LOWER({Name}))";
})() }}

